package daily_assignments;

public class Assignment_07Oct2026_NumAndTheirDouble {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=5;
		int doubleValue=0;
		int i=1;
	
		while (i <= num) {
			doubleValue = i + i;
            System.out.println("Double of " + i + " is : " + doubleValue);
            i++;
        }

	}

}
